    (1::int, 2501::int, 2501::int, 'TIERRA & LAVA, SOCIEDAD ANONIMA'::text, null::text, '99791811'::text, '99791811'::text, null::text, null::text, null::text, null::text, null::text, 1::int, 'S'::text, false::boolean, 'A'::text, 'TIERRA & LAVA'::text, 'TIERRA & LAVA, SOCIEDAD ANONIMA'::text, null::int, false::boolean, null::int, null::text, null::timestamp, null::text, 3::int, null::int, null::text, 0::int, true::boolean, null::text, 1::int, true::boolean, 'PROVEEDOR CREADO AUTOMATICAMENTE DESDE PANTALLA MIGRACION DE FACTURAS SAT'::text),
